{"command": "cd /workspace && cat > gen2.py << 'EOF'
import json, re, math

def note_freq(name):
    names=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
    m=re.match(r'([A-G]#?)(\d)',name)
    pc=names.index(m.group(1)); oct=int(m.group(2))
    midi=12*(oct+1)+pc
    return 440*2**((midi-69)/12)

def TN(name, f0, rel):
    """tool note number for pitch 'name' given sample freq f0 and relative_note rel"""
    f=note_freq(name)
    S=12*math.log2(f/f0)
    return int(round(89-rel+S))

# sample params: (f0, rel)
BASS=(110.0,45); SUB=(55.0,33); PLUCK=(440.0,69); PLUCK2=(440.0,69); LEAD=(440.0,69)
KICK=(50.0,36); SNARE=(200.0,36); HAT=(8000.0,36)

# channels
KICKC,SNAREC,HATC,BASSC,SUBC,PLUCKC,PLUCK2C,LEADC=0,1,2,3,4,5,6,7
# instruments (1-indexed)
IK,IS,IH,IB,ISUB,IP,IP2,IL=6,7,8,1,2,3,4,5

# chord roots per bar: Am G F E
ROOTS=['A1','G1','F1','E1']
ARPS=[['A3','C4','E4','A4'],['G3','B3','D4','G4'],['F3','A3','C4','F4'],['E3','G#3','B3','E4']]
R5=[['A3','E4'],['G3','D4'],['F3','C4'],['E3','B3']]
LEADMELODY=[['E5','C5','A4','C5'],['D5','B4','G4','B4'],['C5','A4','F4','A4'],['B4','G#4','E4','G#4']]

cells=[]
def add(p,row,ch,note,inst,vol,eff=0,effp=0):
    cells.append({"name":"pattern_set_cell","arguments":{"pattern":p,"row":row,"channel":ch,
        "note":note,"instrument":inst,"volume":vol,"effect":eff,"effect_param":effp}})

def bass_riff(p,bar,vol=52):
    r=ROOTS[bar]; f0,rel=BASS
    root=TN(r,f0,rel); root12=TN(r.replace('1','2').replace('0','1') if False else r,f0,rel)+12
    # root+12 semitones
    seq=[root,root,root+12,root, root,root+12,root,root+12, root,root,root+12,root, root,root+12,root,root+12]
    base=bar*16
    for i,nt in enumerate(seq): add(p,base+i,BASSC,nt,IB,vol)

def sub_eighths(p,bar,vol=44):
    r=ROOTS[bar]; f0,rel=SUB; root=TN(r,f0,rel); base=bar*16
    for i in range(8): add(p,base+2*i,SUBC,root,ISUB,vol)
def sub_beats(p,bar,vol=44):
    r=ROOTS[bar]; f0,rel=SUB; root=TN(r,f0,rel); add(p,bar*16,SUBC,root,ISUB,vol)

def arp16(p,bar,ch=PLUCKC,inst=IP,vol=40):
    tones=[TN(t,PLUCK[0],PLUCK[1]) for t in ARPS[bar]]
    pat=[0,1,2,3,2,1,2,3,0,1,2,3,2,1,2,3]; base=bar*16
    for i,idx in enumerate(pat): add(p,base+i,ch,tones[idx],inst,vol)
def arp8(p,bar,ch=PLUCKC,inst=IP,vol=40):
    tones=[TN(t,PLUCK[0],PLUCK[1]) for t in ARPS[bar]]
    pat=[0,1,2,3,2,1,2,3]; base=bar*16
    for i,idx in enumerate(pat): add(p,base+2*i,ch,tones[idx],inst,vol)
def r5_8th(p,bar,vol=32):
    tones=[TN(t,PLUCK2[0],PLUCK2[1]) for t in R5[bar]]; base=bar*16
    for i in range(8): add(p,base+2*i,PLUCK2C,tones[i%2],IP2,vol)
def lead_q(p,bar,vol=44):
    tones=[TN(t,LEAD[0],LEAD[1]) for t in LEADMELODY[bar]]; base=bar*16
    for i,nt in enumerate(tones): add(p,base+4*i,LEADC,nt,IL,vol)

def kick4(p,bar,vol=60):
    nt=TN('C2',KICK[0],KICK[1]); base=bar*16
